import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <!-- Hero Section -->
    <section class="hero">
      <div class="hero-bg"></div>
      <div class="container">
        <div class="hero-content">
          <h1>Khám Phá Việt Nam<br>Cùng Chúng Tôi</h1>
          <p>Hệ thống gợi ý du lịch thông minh, tìm kiếm điểm đến hoàn hảo cho chuyến đi của bạn.</p>
          <div class="hero-actions">
            <a routerLink="/destinations" class="btn btn-primary btn-lg">Khám phá ngay</a>
            <a routerLink="/recommendations" class="btn btn-white btn-lg">Gợi ý AI</a>
          </div>
        </div>
      </div>
    </section>

    <!-- Search Section -->
    <section class="container" style="margin-top:-3rem;position:relative;z-index:10;">
      <div class="search-box">
        <div class="search-form">
          <div class="form-group">
            <label>Điểm đến</label>
            <input type="text" class="form-control" [(ngModel)]="searchKeyword" placeholder="Tìm kiếm địa điểm...">
          </div>
          <div class="form-group">
            <label>Loại hình</label>
            <select class="form-control" [(ngModel)]="searchCategory">
              <option value="">Tất cả</option>
              <option value="bien">Biển & Đảo</option>
              <option value="nui-rung">Núi & Rừng</option>
              <option value="di-tich">Di tích & Lịch sử</option>
              <option value="thien-nhien">Thiên nhiên</option>
              <option value="lang-nghe">Làng nghề</option>
            </select>
          </div>
          <div class="form-group">
            <label>&nbsp;</label>
            <button class="btn btn-primary btn-lg" (click)="search()" style="width:100%;">
              <span class="material-icons">search</span> Tìm kiếm
            </button>
          </div>
        </div>
      </div>
    </section>

    <!-- Featured Destinations -->
    <section class="section">
      <div class="container">
        <div class="section-header">
          <h2>Điểm Đến Nổi Bật</h2>
          <p>Khám phá những địa điểm du lịch đẹp nhất Việt Nam được yêu thích nhất</p>
        </div>
        <div class="loading-spinner" *ngIf="loadingDestinations">
          <div class="spinner"></div>
        </div>
        <div class="grid grid-4" *ngIf="!loadingDestinations">
          <a *ngFor="let d of featuredDestinations" [routerLink]="['/destinations', d.slug]" class="card destination-card fade-in">
            <div class="card-image">
              <img [src]="d.images[0]?.url || 'https://picsum.photos/seed/' + d.slug + '/400/300'" [alt]="d.name">
              <span class="card-badge badge badge-warning" *ngIf="d.isFeatured">Nổi bật</span>
            </div>
            <div class="card-body">
              <div class="card-category">{{ d.category?.name }}</div>
              <h3 class="card-title">{{ d.name }}</h3>
              <p class="card-location">
                <span class="material-icons">location_on</span>
                {{ d.province?.name }}
              </p>
              <div class="card-footer">
                <div class="rating">
                  <span class="score">{{ d.rating }}</span>
                  <span class="stars">★★★★★</span>
                  <span class="count">({{ d.reviewCount }} đánh giá)</span>
                </div>
              </div>
            </div>
          </a>
        </div>
        <div class="text-center mt-4">
          <a routerLink="/destinations" class="btn btn-outline btn-lg">Xem tất cả điểm đến</a>
        </div>
      </div>
    </section>

    <!-- Stats Banner -->
    <section class="stats-banner">
      <div class="container">
        <div class="grid grid-4">
          <div class="stat-item">
            <span class="material-icons">place</span>
            <div>
              <strong>30+</strong>
              <p>Điểm đến</p>
            </div>
          </div>
          <div class="stat-item">
            <span class="material-icons">tour</span>
            <div>
              <strong>15+</strong>
              <p>Tour du lịch</p>
            </div>
          </div>
          <div class="stat-item">
            <span class="material-icons">article</span>
            <div>
              <strong>20+</strong>
              <p>Bài viết</p>
            </div>
          </div>
          <div class="stat-item">
            <span class="material-icons">people</span>
            <div>
              <strong>5000+</strong>
              <p>Du khách</p>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- Featured Tours -->
    <section class="section">
      <div class="container">
        <div class="section-header">
          <h2>Tour Du Lịch Hot</h2>
          <p>Những tour được đặt nhiều nhất, lịch trình hấp dẫn, giá cả hợp lý</p>
        </div>
        <div class="loading-spinner" *ngIf="loadingTours">
          <div class="spinner"></div>
        </div>
        <div class="grid grid-3" *ngIf="!loadingTours">
          <div *ngFor="let t of featuredTours" class="card tour-card fade-in">
            <div class="card-image">
              <img [src]="t.imageUrl || 'https://picsum.photos/seed/' + t.slug + '/400/300'" [alt]="t.name">
              <span class="card-badge badge badge-primary" *ngIf="t.discountPrice">{{ getDiscount(t) }}% OFF</span>
            </div>
            <div class="card-body">
              <h3 class="card-title">{{ t.name }}</h3>
              <p class="card-duration">
                <span class="material-icons">schedule</span>
                {{ t.duration }}
              </p>
              <div class="tour-pricing">
                <span class="price-old" *ngIf="t.discountPrice">{{ t.price | number:'1.0-0' }}đ</span>
                <span class="price">{{ (t.discountPrice || t.price) | number:'1.0-0' }}đ</span>
                <span class="per-person">/người</span>
              </div>
              <div class="card-actions">
                <a [routerLink]="['/tours', t.slug]" class="btn btn-primary">Chi tiết</a>
                <button class="btn btn-outline" (click)="requestTour(t)">Tư vấn</button>
              </div>
            </div>
          </div>
        </div>
        <div class="text-center mt-4">
          <a routerLink="/tours" class="btn btn-outline btn-lg">Xem tất cả tour</a>
        </div>
      </div>
    </section>

    <!-- Recent Articles -->
    <section class="section bg-light">
      <div class="container">
        <div class="section-header">
          <h2>Cẩm Nang Du Lịch</h2>
          <p>Kinh nghiệm, mẹo hay và lịch trình từ những người đã đi</p>
        </div>
        <div class="loading-spinner" *ngIf="loadingArticles">
          <div class="spinner"></div>
        </div>
        <div class="grid grid-3" *ngIf="!loadingArticles">
          <a *ngFor="let a of recentArticles" [routerLink]="['/articles', a.slug]" class="card article-card fade-in">
            <div class="card-image">
              <img [src]="a.imageUrl || 'https://picsum.photos/seed/' + a.slug + '/400/250'" [alt]="a.title">
              <span class="badge badge-primary card-cat">{{ a.category?.name }}</span>
            </div>
            <div class="card-body">
              <h3 class="card-title">{{ a.title }}</h3>
              <p class="card-excerpt">{{ a.excerpt }}</p>
              <div class="card-meta">
                <span class="material-icons">visibility</span> {{ a.viewCount }}
                <span class="material-icons">calendar_today</span> {{ a.publishedAt | date:'dd/MM/yyyy' }}
              </div>
            </div>
          </a>
        </div>
        <div class="text-center mt-4">
          <a routerLink="/articles" class="btn btn-outline btn-lg">Xem tất cả bài viết</a>
        </div>
      </div>
    </section>

    <!-- AI Recommendation CTA -->
    <section class="ai-cta">
      <div class="container">
        <div class="ai-cta-content">
          <span class="material-icons">psychology</span>
          <h2>Gợi ý Thông Minh Bằng AI</h2>
          <p>Trả lời vài câu hỏi đơn giản, chúng tôi sẽ gợi ý những điểm đến phù hợp nhất với bạn.</p>
          <a routerLink="/recommendations" class="btn btn-accent btn-lg">
            <span class="material-icons">auto_awesome</span>
            Bắt đầu gợi ý
          </a>
        </div>
      </div>
    </section>

    <!-- Quick Contact -->
    <section class="section">
      <div class="container">
        <div class="quick-contact">
          <div class="contact-info">
            <h2>Liên Hệ Ngay</h2>
            <p>Bạn cần tư vấn về tour du lịch? Để lại thông tin, chúng tôi sẽ liên hệ lại ngay!</p>
          </div>
          <div class="contact-form">
            <div class="grid grid-2">
              <input type="text" class="form-control" [(ngModel)]="contactName" placeholder="Họ tên của bạn">
              <input type="email" class="form-control" [(ngModel)]="contactEmail" placeholder="Email của bạn">
            </div>
            <textarea class="form-control" [(ngModel)]="contactMessage" placeholder="Bạn cần tư vấn về..."></textarea>
            <button class="btn btn-primary btn-lg" (click)="submitQuickContact()">
              <span class="material-icons">send</span>
              Gửi yêu cầu
            </button>
            <p class="contact-success" *ngIf="contactSuccess">Gửi thành công! Chúng tôi sẽ liên hệ sớm.</p>
          </div>
        </div>
      </div>
    </section>
  `,
  styles: [`
    .hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }

    .destination-card, .tour-card, .article-card {
      text-decoration: none;
      color: inherit;
      display: block;
    }

    .card-image {
      position: relative;
      height: 200px;
      overflow: hidden;

      img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        transition: transform 0.4s;
      }
    }

    .card:hover .card-image img { transform: scale(1.08); }

    .card-badge {
      position: absolute;
      top: 12px;
      right: 12px;
    }

    .card-category {
      font-size: 0.8125rem;
      color: var(--primary);
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 0.25rem;
    }

    .card-title {
      font-size: 1.0625rem;
      margin-bottom: 0.5rem;
      line-height: 1.3;
    }

    .card-location {
      display: flex;
      align-items: center;
      gap: 0.25rem;
      color: var(--gray);
      font-size: 0.875rem;
      margin-bottom: 0.75rem;
      .material-icons { font-size: 1rem; }
    }

    .card-footer { border-top: 1px solid #f1f5f9; padding-top: 0.75rem; }

    .card-duration {
      display: flex;
      align-items: center;
      gap: 0.25rem;
      color: var(--gray);
      font-size: 0.875rem;
      margin-bottom: 0.75rem;
      .material-icons { font-size: 1rem; }
    }

    .tour-pricing {
      margin-bottom: 1rem;
      .price-old { text-decoration: line-through; color: var(--gray-light); font-size: 0.875rem; margin-right: 0.5rem; }
      .price { font-size: 1.25rem; font-weight: 700; color: var(--danger); }
      .per-person { color: var(--gray); font-size: 0.875rem; }
    }

    .card-actions { display: flex; gap: 0.5rem; }
    .card-actions .btn { flex: 1; }

    .card-excerpt {
      color: var(--gray);
      font-size: 0.9375rem;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
      margin-bottom: 0.75rem;
    }

    .card-meta {
      display: flex;
      gap: 1rem;
      color: var(--gray);
      font-size: 0.8125rem;
      align-items: center;
      .material-icons { font-size: 1rem; }
    }

    .card-cat { position: absolute; bottom: 12px; left: 12px; }

    .stats-banner {
      background: linear-gradient(135deg, var(--primary) 0%, #5a67d8 100%);
      padding: 3rem 0;
      color: white;
      margin: 2rem 0;
    }

    .stat-item {
      display: flex;
      align-items: center;
      gap: 1rem;
      justify-content: center;

      .material-icons { font-size: 2.5rem; opacity: 0.9; }
      strong { font-size: 2rem; font-weight: 700; display: block; }
      p { margin: 0; opacity: 0.9; }
    }

    .bg-light { background: #f8fafc; }

    .ai-cta {
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      padding: 4rem 0;
      text-align: center;
      color: white;
    }

    .ai-cta-content {
      max-width: 600px;
      margin: 0 auto;

      .material-icons { font-size: 3rem; margin-bottom: 1rem; opacity: 0.9; }
      h2 { color: white; margin-bottom: 0.75rem; }
      p { font-size: 1.125rem; opacity: 0.9; margin-bottom: 1.5rem; }
    }

    .quick-contact {
      display: grid;
      grid-template-columns: 1fr 1.5fr;
      gap: 3rem;
      align-items: center;

      @media (max-width: 768px) {
        grid-template-columns: 1fr;
      }
    }

    .contact-info h2 { margin-bottom: 0.5rem; }
    .contact-info p { color: var(--gray); }

    .contact-form {
      display: flex;
      flex-direction: column;
      gap: 1rem;
    }

    .contact-success {
      color: var(--secondary);
      font-weight: 600;
      margin: 0;
    }
  `]
})
export class HomeComponent implements OnInit {
  featuredDestinations: any[] = [];
  featuredTours: any[] = [];
  recentArticles: any[] = [];
  loadingDestinations = true;
  loadingTours = true;
  loadingArticles = true;
  searchKeyword = '';
  searchCategory = '';
  contactName = '';
  contactEmail = '';
  contactMessage = '';
  contactSuccess = false;

  constructor(private api: ApiService) {}

  ngOnInit() {
    this.loadFeaturedDestinations();
    this.loadFeaturedTours();
    this.loadRecentArticles();
  }

  loadFeaturedDestinations() {
    this.api.getFeaturedDestinations().subscribe({
      next: (data) => { this.featuredDestinations = data; this.loadingDestinations = false; },
      error: () => { this.loadingDestinations = false; }
    });
  }

  loadFeaturedTours() {
    this.api.getFeaturedTours().subscribe({
      next: (data) => { this.featuredTours = data; this.loadingTours = false; },
      error: () => { this.loadingTours = false; }
    });
  }

  loadRecentArticles() {
    this.api.getRecentArticles().subscribe({
      next: (data) => { this.recentArticles = data; this.loadingArticles = false; },
      error: () => { this.loadingArticles = false; }
    });
  }

  search() {
    const params: any = {};
    if (this.searchKeyword) params.search = this.searchKeyword;
    if (this.searchCategory) params.category = this.searchCategory;
    window.location.href = `/destinations?${Object.entries(params).map(([k,v]) => `${k}=${v}`).join('&')}`;
  }

  getDiscount(tour: any): number {
    if (!tour.discountPrice) return 0;
    return Math.round((1 - tour.discountPrice / tour.price) * 100);
  }

  requestTour(tour: any) {
    window.location.href = '/contact';
  }

  submitQuickContact() {
    if (!this.contactName || !this.contactEmail || !this.contactMessage) return;
    this.api.createInquiry({
      name: this.contactName,
      email: this.contactEmail,
      message: this.contactMessage,
      subject: 'Yêu cầu tư vấn nhanh từ trang chủ',
      type: 'contact'
    }).subscribe({
      next: () => {
        this.contactSuccess = true;
        this.contactName = '';
        this.contactEmail = '';
        this.contactMessage = '';
        setTimeout(() => this.contactSuccess = false, 5000);
      }
    });
  }
}
